import { LIVE_TILE_MIN_PX, MAX_LEVEL, MIN_LEVEL, SUB_PIXEL_PX, TILE_SIZE } from "./constants";
import { type BBox, clampLevel, nativeLevel, tileIndex } from "./tile";

export type LevelRange = {
  level: number;
  minTx: number;
  minTy: number;
  maxTx: number;
  maxTy: number;
};

export type ViewTiles = { native: number; live: LevelRange[]; snapshot: LevelRange[] };

export function levelRange(level: number, bounds: BBox): LevelRange {
  return {
    level,
    minTx: tileIndex(level, bounds.minX),
    minTy: tileIndex(level, bounds.minY),
    maxTx: tileIndex(level, bounds.maxX),
    maxTy: tileIndex(level, bounds.maxY),
  };
}

function levelForScreenSize(px: number, zoom: number): number {
  return clampLevel(Math.ceil(Math.log2(px / (TILE_SIZE * zoom))));
}

export function finestLevel(zoom: number): number {
  return levelForScreenSize(SUB_PIXEL_PX, zoom);
}

export function finestLiveLevel(zoom: number): number {
  return levelForScreenSize(LIVE_TILE_MIN_PX, zoom);
}

export function viewTiles(bounds: BBox, zoom: number): ViewTiles {
  const native = nativeLevel(zoom);
  const liveFrom = finestLiveLevel(zoom);
  const live: LevelRange[] = [];
  const snapshot: LevelRange[] = [];
  for (let level = MAX_LEVEL; level >= Math.max(MIN_LEVEL, finestLevel(zoom)); level--) {
    (level >= liveFrom ? live : snapshot).push(levelRange(level, bounds));
  }
  return { native, live, snapshot };
}

export function isSubPixel(bbox: BBox, zoom: number): boolean {
  return Math.max(bbox.maxX - bbox.minX, bbox.maxY - bbox.minY) * zoom < SUB_PIXEL_PX;
}
import { z } from "zod";

export const objectId = z.string().regex(/^[0-9A-Za-z_-]{1,64}$/);

export const nativeZoom = z.int().min(-40).max(40);

export const bbox = z.strictObject({
  minX: z.number(),
  minY: z.number(),
  maxX: z.number(),
  maxY: z.number(),
});

export const colour = z.int().min(0).max(5);

export const pencilSize = z.enum(["Small", "Medium", "Large"]);

export const point = z.tuple([z.number(), z.number(), z.number().min(0).max(1)]);

export const stroke = z.strictObject({
  type: z.literal("Stroke"),
  objectId,
  nativeZoom,
  bbox,
  colour,
  size: pencilSize,
  points: z.array(point).min(1).max(4096),
});

export const shape = z.strictObject({
  type: z.literal("Shape"),
  objectId,
  nativeZoom,
  bbox,
  colour,
  size: pencilSize,
  shape: z.enum(["Rectangle", "Ellipse", "Line"]),
});

export const text = z.strictObject({
  type: z.literal("Text"),
  objectId,
  nativeZoom,
  bbox,
  colour,
  size: pencilSize,
  text: z.string().min(1).max(4096),
});

export const stallionObject = z.discriminatedUnion("type", [stroke, shape, text]);

export type Bbox = z.infer<typeof bbox>;
export type Point = z.infer<typeof point>;
export type PencilSize = z.infer<typeof pencilSize>;
export type Stroke = z.infer<typeof stroke>;
export type Shape = z.infer<typeof shape>;
export type Text = z.infer<typeof text>;
export type StallionObject = z.infer<typeof stallionObject>;
import { z } from "zod";
import { colour, nativeZoom, objectId, pencilSize, point } from "./model";

export const MAX_INK_POINTS = 4096;

export const inkFrame = z.strictObject({
  strokeId: objectId,
  colour,
  size: pencilSize,
  nativeZoom,
  from: z.int().min(0).max(MAX_INK_POINTS),
  points: z.array(point).max(MAX_INK_POINTS),
});

export type InkFrame = z.infer<typeof inkFrame>;
import { Encoder } from "cbor-x";
import { validate } from "../generated/validate.js";
import type { StallionObject } from "./model";

export type DecodeResult = { ok: true; value: StallionObject } | { ok: false; error: string };

const cbor = new Encoder({ useRecords: false, mapsAsObjects: true, variableMapSize: true });

const describeErrors = (): string =>
  (validate.errors ?? []).map((e) => `${e.instancePath || "/"} ${e.message ?? ""}`).join("; ");

export const encode = (object: StallionObject): Uint8Array => {
  if (!validate(object)) {
    throw new TypeError(`Cannot encode an invalid object: ${describeErrors()}`);
  }
  return cbor.encode(object);
};

export const decode = (bytes: Uint8Array): DecodeResult => {
  const value: unknown = cbor.decode(bytes);
  if (!validate(value)) {
    return { ok: false, error: describeErrors() };
  }
  return { ok: true, value };
};
import { Encoder } from "cbor-x";
import { z } from "zod";

export const frameKind = z.enum([
  "Subscribe",
  "Unsubscribe",
  "Sync",
  "Awareness",
  "Reject",
  "View",
  "Snapshot",
  "Move",
]);

export const frame = z.strictObject({
  tileKey: z.string(),
  kind: frameKind,
  payload: z.instanceof(Uint8Array),
});

export type FrameKind = z.infer<typeof frameKind>;
export type Frame = z.infer<typeof frame>;

export const BOARD_KEY = "";

export type FrameResult = { ok: true; value: Frame } | { ok: false; error: string };

const cbor = new Encoder({
  useRecords: false,
  mapsAsObjects: true,
  variableMapSize: true,
  tagUint8Array: false,
});

export const encodeFrame = (value: Frame): Uint8Array =>
  cbor.encode({ tileKey: value.tileKey, kind: value.kind, payload: value.payload });

export const decodeFrame = (bytes: Uint8Array): FrameResult => {
  const parsed = frame.safeParse(cbor.decode(bytes));
  if (!parsed.success) {
    return { ok: false, error: parsed.error.message };
  }
  return { ok: true, value: parsed.data };
};

export const move = z.strictObject({
  objectId: z.string(),
  fromTile: z.string(),
  toTile: z.string(),
  fromUpdate: z.instanceof(Uint8Array),
  toUpdate: z.instanceof(Uint8Array),
});

export type Move = z.infer<typeof move>;

export type MoveResult = { ok: true; value: Move } | { ok: false; error: string };

export const encodeMove = (value: Move): Uint8Array =>
  cbor.encode({
    objectId: value.objectId,
    fromTile: value.fromTile,
    toTile: value.toTile,
    fromUpdate: value.fromUpdate,
    toUpdate: value.toUpdate,
  });

export const decodeMove = (bytes: Uint8Array): MoveResult => {
  const parsed = move.safeParse(cbor.decode(bytes));
  if (!parsed.success) {
    return { ok: false, error: parsed.error.message };
  }
  return { ok: true, value: parsed.data };
};

