import { Redirect, useLocation } from "wouter-preact";
import { Board } from "./board";
import { boardIdFromPath } from "./board-path";
import { Landing } from "./landing";

export function App() {
  const [location] = useLocation();
  const boardId = boardIdFromPath(location);
  if (boardId !== undefined) return <Board key={boardId} boardId={boardId} />;
  if (location === "/") return <Landing />;
  return <Redirect to="/" replace />;
}
import { render } from "preact";
import { App } from "./app";
import { UpdateNotice } from "./update-notice";
import "./styles.css";

export const mount = (root: HTMLElement): void =>
  render(
    <>
      <App />
      <UpdateNotice />
    </>,
    root,
  );
import { boot, showBootFailure } from "./boot";

const root = document.getElementById("app");
if (!root) throw new Error("Missing #app root element in index.html");
boot(
  root,
  () => import("./mount"),
  (message) => showBootFailure(root, message),
);
export const MAX_SLUG_LENGTH = 60;

export const boardSlug = (name: string): string =>
  name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, MAX_SLUG_LENGTH)
    .replace(/-+$/, "");

export const boardPath = (boardId: string, name: string): string => {
  const base = `/b/${encodeURIComponent(boardId)}`;
  const slug = name === boardId ? "" : boardSlug(name);
  return slug ? `${base}/${slug}` : base;
};

const decodeSegment = (segment: string): string => {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
};

const BOARD_PATH = /^\/b\/([^/]+)(?:\/[^/]*)?\/?$/;

export const boardIdFromPath = (pathname: string): string | undefined => {
  const match = BOARD_PATH.exec(pathname);
  return match?.[1] ? decodeSegment(match[1]) : undefined;
};
