  let drag: DragMode = { mode: "Idle" };
  let pinch: PinchMode = { mode: "Idle" };
  let penSeen = false;

  const wantsPan = (input: DragInput, modifiers: Modifiers): boolean => {
    if (input.button === MIDDLE) return true;
    if (input.button !== PRIMARY) return false;
    if (modifiers.panTool || modifiers.spaceDown) return true;
    return input.kind === "touch" && penSeen;
  };

  const promote = (): Effect[] => {
    if (drag.mode !== "Pending") return [];
    const { point } = drag;
    drag = { mode: "Draw", kind: "touch" };
    return [{ type: "StartStroke", secondary: false, point }];
  };

  const begin = (input: DragInput, modifiers: Modifiers): Effect[] => {
    if (input.kind === "pen") penSeen = true;
    if (pinch.mode === "Track") {
      drag = { mode: "Ignore" };
      return [];
    }
    if (wantsPan(input, modifiers)) {
      drag = { mode: "Pan", point: input.point };
      return [];
    }
    if (input.button !== PRIMARY && input.button !== SECONDARY) {
      drag = { mode: "Ignore" };
      return [];
    }
    if (input.kind === "touch") {
      drag = { mode: "Pending", point: input.point, time: input.time };
      return [];
    }
    drag = { mode: "Draw", kind: input.kind };
    return [{ type: "StartStroke", secondary: input.button === SECONDARY, point: input.point }];
  };

  const step = (input: DragInput): Effect[] => {
    const effects: Effect[] = [];
    if (drag.mode === "Pending") {
      if (!input.intentional && input.time - drag.time < PENDING_MS) return [];
      effects.push(...promote());
    }
    if (drag.mode === "Draw") effects.push({ type: "ExtendStroke" });
    if (drag.mode === "Pan") {
      effects.push({
        type: "Pan",
        dx: input.point.x - drag.point.x,
        dy: input.point.y - drag.point.y,
      });
      drag = { mode: "Pan", point: input.point };
    }
    return effects;
  const apply = (effects: readonly Effect[], event?: PointerEvent) => {
    for (const effect of effects) {
      switch (effect.type) {
        case "StartStroke": {
          const tool = currentTool();
          if (tool.mode === "Select") {
            startDrag(effect.point);
            break;
          }
          if (tool.mode === "Eraser") {
            eraser = undefined;
            eraseTo(effect.point);
            break;
          }
          draft = startDraft(
            effect.secondary ? tool.secondary : tool.primary,
            tool.size,
            camera.zoom,
          );
          shareDraft(draft);
          addPoint(effect.point, event ? pressureOf(event) : 0.5);
          break;
        }
        case "ExtendStroke": {
          if (!event) break;
          const samples = event.getCoalescedEvents?.() ?? [];
          for (const sample of samples.length > 0 ? samples : [event]) {
            if (drag) dragTo(localPoint(sample));
            else if (eraser) eraseTo(localPoint(sample));
            else addPoint(localPoint(sample), pressureOf(sample));
          }
          break;
        }
        case "CommitStroke":
          eraser = undefined;
          drop();
    event.preventDefault();
    stopAnimation();
    follow.stop();
    const factor = wheelFactor(event.ctrlKey ? event.deltaY * 3 : event.deltaY, event.deltaMode);
    moveCamera(zoomAt(camera, localPoint(event), factor));
  };

  const onPointerMove = (event: PointerEvent) => shareCursor(localPoint(event));

  const onKey = (event: KeyboardEvent) => {
    if (event.target instanceof HTMLInputElement) return;
    if (event.type === "keydown" && (event.key === "Delete" || event.key === "Backspace")) {
      if (selected === undefined || currentTool().mode !== "Select") return;
      event.preventDefault();
      source.erase(selected);
      source.history.checkpoint();
      selected = undefined;
      requestRender();
      return;
    }
    if (event.code !== "Space") return;
    event.preventDefault();
    spaceDown = event.type === "keydown";
  };

  const onPointerLeave = () => shareCursor(undefined);

  const preventDefault = (event: Event) => event.preventDefault();

  const unobserve = source.objects.observe(onObjects);
  awareness?.on("change", onAwareness);
