name: deploy

on:
  push:
    branches: [main]
  workflow_dispatch:

concurrency:
  group: smoke
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  smoke:
    runs-on: ubuntu-latest
    timeout-minutes: 30
    env:
      CF_ACCESS_CLIENT_ID: ${{ secrets.CF_ACCESS_CLIENT_ID }}
      CF_ACCESS_CLIENT_SECRET: ${{ secrets.CF_ACCESS_CLIENT_SECRET }}
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version: 24
          cache: npm
      - run: npm ci
      - run: npx playwright install --with-deps chromium-headless-shell
      - name: Wait for Workers Builds to serve this commit
        run: npm run wait:live -- "$GITHUB_SHA"
      - name: Smoke through Access
        run: npm run smoke -- "https://stallion.matthijs-f49.workers.dev/b/ci-${{ github.run_id }}"
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

if (process.env.WORKERS_CI !== "1") {
  console.error(
    "npm run deploy runs only inside Cloudflare Workers Builds; push to main to deploy",
  );
  process.exit(1);
}

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const vars = JSON.parse(readFileSync(join(root, "infra", "access.json"), "utf8"));
const value = (name) => {
  if (!vars[name]) {
    console.error(`infra/access.json has no ${name}; run npm run infra:apply`);
    process.exit(1);
  }
  return vars[name];
};

const run = spawnSync(
  "npx",
  [
    "wrangler",
    "deploy",
    "--var",
    `ACCESS_TEAM_DOMAIN:${value("ACCESS_TEAM_DOMAIN")}`,
    "--var",
    `ACCESS_AUD:${value("ACCESS_AUD")}`,
  ],
  { cwd: root, stdio: "inherit" },
);
if (run.error) throw run.error;
process.exit(run.status ?? 1);
#!/bin/sh
set -eu

cd "$(dirname "$0")/.."

cargo_bin="${CARGO_HOME:-$HOME/.cargo}/bin"
PATH="$cargo_bin:$PATH"
export PATH

if ! command -v rustup >/dev/null 2>&1; then
  curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs |
    sh -s -- -y --profile minimal --default-toolchain none --no-modify-path
fi

rustup toolchain install

if ! command -v worker-build >/dev/null 2>&1; then
  cargo install --locked worker-build@^0.8
fi

cd crates/server
exec worker-build --release
import { accessHeaders } from "./env.mjs";

const [commit, origin = "https://stallion.matthijs-f49.workers.dev"] = process.argv.slice(2);
if (!commit) {
  console.error("usage: node npm-scripts/wait-live.mjs <commit sha> [origin]");
  process.exit(2);
}

const TIMEOUT_MS = 15 * 60_000;
const INTERVAL_MS = 20_000;
const probe = new URL("/api/me/boards", origin);
const deadline = Date.now() + TIMEOUT_MS;
let live = "";

while (Date.now() < deadline) {
  const response = await fetch(probe, { headers: accessHeaders(), redirect: "manual" }).catch(
    (error) => {
      console.log(`${probe} failed: ${error.message}`);
      return undefined;
    },
  );
  live = response?.headers.get("x-stallion-commit") ?? "";
  if (live === commit) {
    console.log(`${origin} serves ${commit}`);
    process.exit(0);
  }
  console.log(
    `${origin} serves ${live || "no x-stallion-commit"} (status ${response?.status}); waiting for ${commit}`,
  );
  await new Promise((resolve) => setTimeout(resolve, INTERVAL_MS));
}

console.error(
  `${origin} still serves ${live || "no x-stallion-commit"} after 15 minutes, not ${commit}; check the Workers Builds log for the stallion Worker`,
);
process.exit(1);
